style.css:
/* ==UserStyle==
@name           Neon Arcade Dark (Original)
@namespace      github.com/openai/chatgpt
@version        1.0.0
@description    Custom neon arcade theme - NOT a copy of any site
@author         You
==/UserStyle== */

/* Background */
body {
    background: radial-gradient(circle at top, #0f172a, #020617) !important;
    color: #e2e8f0 !important;
    font-family: 'Segoe UI', sans-serif !important;
}

/* Buttons */
button {
    background: linear-gradient(135deg, #06b6d4, #9333ea) !important;
    border: none !important;
    border-radius: 14px !important;
    color: white !important;
    padding: 10px 16px !important;
    font-weight: 600 !important;
    box-shadow: 0 0 12px rgba(147, 51, 234, 0.6) !important;
    transition: all 0.25s ease !important;
}

button:hover {
    transform: scale(1.08);
    box-shadow: 0 0 18px rgba(6, 182, 212, 0.9) !important;
}

/* Cards / Panels */
div {
    border-radius: 16px !important;
}

/* Game boxes feel */
[class*="card"], [class*="box"] {
    background: rgba(15, 23, 42, 0.85) !important;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(147, 51, 234, 0.3);
    box-shadow: 0 0 20px rgba(147, 51, 234, 0.2);
}

/* Top bar */
header, nav {
    background: rgba(2, 6, 23, 0.9) !important;
    border-bottom: 1px solid rgba(6, 182, 212, 0.4);
}

/* Text glow effect */
h1, h2, h3 {
    color: #38bdf8 !important;
    text-shadow: 0 0 10px rgba(56, 189, 248, 0.8);
}

/* Inputs */
input {
    background: #020617 !important;
    border: 1px solid #06b6d4 !important;
    border-radius: 10px !important;
    color: white !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(#06b6d4, #9333ea);
    border-radius: 10px;
}
